/// Tiny seeded Xorshift RNG — used only for spawn jitter so determinism
/// holds across runs with the same seed. The physics engine itself uses no RNG.
pub struct SeededRng {
    state: u64,
}

impl SeededRng {
    pub fn new(seed: u64) -> Self {
        // Avoid all-zero state (Xorshift would lock up).
        let state = if seed == 0 { 1 } else { seed };
        Self { state }
    }

    /// Returns a f64 in [0, 1).
    pub fn f64(&mut self) -> f64 {
        self.state ^= self.state << 13;
        self.state ^= self.state >> 7;
        self.state ^= self.state << 17;
        // Use upper 53 bits for double precision.
        (self.state >> 11) as f64 * (1.0 / (1u64 << 53) as f64)
    }

    /// Returns a f64 in [-spread, +spread).
    pub fn jitter(&mut self, spread: f64) -> f64 {
        (self.f64() - 0.5) * 2.0 * spread
    }

    pub fn seed(&self) -> u64 {
        self.state
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_deterministic_sequence() {
        let mut a = SeededRng::new(42);
        let mut b = SeededRng::new(42);
        for _ in 0..100 {
            assert_eq!(a.f64(), b.f64());
        }
    }

    #[test]
    fn test_different_seeds_differ() {
        let mut a = SeededRng::new(42);
        let mut b = SeededRng::new(99);
        let mut same = true;
        for _ in 0..10 {
            if (a.f64() - b.f64()).abs() > f64::EPSILON {
                same = false;
                break;
            }
        }
        assert!(!same);
    }
}

