use serde::{Deserialize, Serialize};

/// Gravity direction modes.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum Gravity {
    Down,
    Up,
    ZeroG,
}

impl Gravity {
    pub fn cycle(self) -> Self {
        match self {
            Gravity::Down => Gravity::Up,
            Gravity::Up => Gravity::ZeroG,
            Gravity::ZeroG => Gravity::Down,
        }
    }

    pub fn acceleration(self) -> (f32, f32) {
        match self {
            Gravity::Down => (0.0, 980.0),
            Gravity::Up => (0.0, -980.0),
            Gravity::ZeroG => (0.0, 0.0),
        }
    }

    pub fn label(&self) -> &'static str {
        match self {
            Gravity::Down => "Down",
            Gravity::Up => "Up",
            Gravity::ZeroG => "Zero-G",
        }
    }
}

/// A static peg on the board.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Peg {
    pub x: f32,
    pub y: f32,
    pub radius: f32,
    pub hit_count: u32,
}

impl Peg {
    pub fn new(x: f32, y: f32) -> Self {
        Self {
            x,
            y,
            radius: 8.0,
            hit_count: 0,
        }
    }
}

/// A dynamic ball.
#[derive(Clone, Debug)]
pub struct Ball {
    pub x: f32,
    pub y: f32,
    pub vx: f32,
    pub vy: f32,
    pub radius: f32,
}

impl Ball {
    pub fn new(x: f32, y: f32, vx: f32, vy: f32) -> Self {
        Self {
            x,
            y,
            vx,
            vy,
            radius: 5.0,
        }
    }
}

pub const MAX_PEGS: usize = 64;
pub const MAX_BALLS: usize = 32;
pub const BOARD_W: f32 = 800.0;
pub const BOARD_H: f32 = 600.0;

/// The main board state.
#[derive(Clone)]
pub struct Board {
    pub pegs: Vec<Peg>,
    pub balls: Vec<Ball>,
    pub gravity: Gravity,
    pub total_hits: u32,
    pub seed: u64,
    pub tick_count: u64,
}

impl Board {
    pub fn new(seed: u64) -> Self {
        Self {
            pegs: Vec::with_capacity(MAX_PEGS),
            balls: Vec::with_capacity(MAX_BALLS),
            gravity: Gravity::Down,
            total_hits: 0,
            seed,
            tick_count: 0,
        }
    }

    pub fn add_peg(&mut self, x: f32, y: f32) -> Result<(), &'static str> {
        if self.pegs.len() >= MAX_PEGS {
            return Err("Peg budget exhausted (max 64)");
        }
        // Reject spawn if overlapping an existing peg.
        for p in &self.pegs {
            let dx = p.x - x;
            let dy = p.y - y;
            let min_dist = p.radius + 8.0; // peg + new peg min
            if dx * dx + dy * dy < min_dist * min_dist {
                return Err("Overlaps existing peg");
            }
        }
        self.pegs.push(Peg::new(x, y));
        Ok(())
    }

    pub fn remove_peg_at(&mut self, x: f32, y: f32) -> bool {
        if let Some(idx) = self
            .pegs
            .iter()
            .position(|p| ((p.x - x).powi(2) + (p.y - y).powi(2)).sqrt() < p.radius + 4.0)
        {
            self.pegs.remove(idx);
            true
        } else {
            false
        }
    }

    pub fn add_ball(&mut self, x: f32, y: f32, vx: f32, vy: f32) {
        if self.balls.len() >= MAX_BALLS {
            // Despawn oldest ball (front of queue).
            self.balls.remove(0);
        }
        // Reject spawn overlapping any peg.
        for p in &self.pegs {
            let dx = p.x - x;
            let dy = p.y - y;
            let min_dist = p.radius + 5.0;
            if dx * dx + dy * dy < min_dist * min_dist {
                return; // silently reject
            }
        }
        self.balls.push(Ball::new(x, y, vx, vy));
    }

    pub fn clear_balls(&mut self) {
        self.balls.clear();
    }

    pub fn reset_counters(&mut self) {
        for p in &mut self.pegs {
            p.hit_count = 0;
        }
        self.total_hits = 0;
    }

    pub fn hot_peg(&self) -> Option<(usize, u32, f64)> {
        if self.total_hits == 0 || self.pegs.is_empty() {
            return None;
        }
        let (idx, &count) = self
            .pegs
            .iter()
            .enumerate()
            .map(|(i, p)| (i, p.hit_count))
            .max_by_key(|&(_, c)| c)?;
        let pct = count as f64 / self.total_hits as f64 * 100.0;
        Some((idx, count, pct))
    }

    pub fn peg_count(&self) -> usize {
        self.pegs.len()
    }
}

