                b.vx = -b.vx * WALL_RESTITUTION;
            }
            if b.x + b.radius > BOARD_W {
                b.x = BOARD_W - b.radius;
                b.vx = -b.vx * WALL_RESTITUTION;
            }
            if b.y - b.radius < 0.0 {
                b.y = b.radius;
                b.vy = -b.vy * WALL_RESTITUTION;
            }
            if b.y + b.radius > BOARD_H {
                b.y = BOARD_H - b.radius;
                b.vy = -b.vy * WALL_RESTITUTION;
            }
        }

        // Ball ↔ ball collisions.
        for i in 0..balls.len() {
            for j in (i + 1)..balls.len() {
                resolve_ball_ball(&mut balls[i], &mut balls[j]);
            }
        }

        // Ball ↔ peg collisions.
        for b in balls.iter_mut() {
            for p in pegs.iter_mut() {
                if resolve_ball_peg(b, p) {
                    p.hit_count += 1;
                    hits += 1;
                }
            }
        }
    }
    hits
}

/// Resolve collision between two balls (equal mass).
fn resolve_ball_ball(a: &mut Ball, b: &mut Ball) {
    let dx = b.x - a.x;
    let dy = b.y - a.y;
    let dist_sq = dx * dx + dy * dy;
    let min_dist = a.radius + b.radius;
    if dist_sq >= min_dist * min_dist || dist_sq < f32::EPSILON {
        return;
    }
    let dist = dist_sq.sqrt();
    let nx = dx / dist;
    let ny = dy / dist;
    let overlap = min_dist - dist;

    // Positional correction (equal mass → split equally).
    a.x -= nx * overlap * 0.5;
    a.y -= ny * overlap * 0.5;
    b.x += nx * overlap * 0.5;
    b.y += ny * overlap * 0.5;

    // Relative velocity along collision normal.
    let dvx = a.vx - b.vx;
    let dvy = a.vy - b.vy;
    let rel_vn = dvx * nx + dvy * ny;
    if rel_vn > 0.0 {
        // Moving apart — no impulse needed.
        return;
    }
    let impulse = -(1.0 + RESTITUTION) * rel_vn * 0.5; // equal mass
    a.vx += impulse * nx;
    a.vy += impulse * ny;
    b.vx -= impulse * nx;
    b.vy -= impulse * ny;
}

/// Resolve collision between a ball and a static peg.
/// Returns true if a collision occurred.
fn resolve_ball_peg(ball: &mut Ball, peg: &Peg) -> bool {
    let dx = ball.x - peg.x;
    let dy = ball.y - peg.y;
    let dist_sq = dx * dx + dy * dy;
    let min_dist = ball.radius + peg.radius;
    if dist_sq >= min_dist * min_dist || dist_sq < f32::EPSILON {
        return false;
    }
    let dist = dist_sq.sqrt();
    let nx = dx / dist;
    let ny = dy / dist;
    let overlap = min_dist - dist;

    // Positional correction (peg is static → ball moves fully).
    ball.x += nx * overlap;
    ball.y += ny * overlap;

    // Relative velocity along collision normal.
    let rel_vn = ball.vx * nx + ball.vy * ny;
    if rel_vn > 0.0 {
        return false; // moving away
    }
    let impulse = -(1.0 + RESTITUTION) * rel_vn;
    ball.vx += impulse * nx;
    ball.vy += impulse * ny;
    true
}

/// Run a full headless simulation and return a summary.
pub fn simulate_headless(
    pegs: &[Peg],
    seed: u64,
    ticks: u64,
    gravity: crate::board::Gravity,
) -> PhysicsSummary {
    let mut balls: Vec<Ball> = Vec::new();
    let mut pegs_clone: Vec<Peg> = pegs.to_vec();
    let (gx, gy) = gravity.acceleration();

    // Spawn a single deterministic ball from top chute.
    let mut rng = crate::determinism::SeededRng::new(seed);
    let bx = BOARD_W * 0.5 + rng.jitter(20.0);
    let by = 30.0;
    balls.push(Ball::new(bx, by, 0.0, 50.0));

    let total_hits = step(&mut balls, &mut pegs_clone, gx, gy, ticks);

    let hot = pegs_clone
        .iter()
        .enumerate()
        .max_by_key(|(_, p)| p.hit_count);

    let ball_positions: Vec<(f32, f32)> = balls.iter().map(|b| (b.x, b.y)).collect();

    PhysicsSummary {
        ball_positions,
        total_hits,
        hot_peg_id: hot.map(|(i, _)| i),
        hot_peg_hits: hot.map(|(_, p)| p.hit_count).unwrap_or(0),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::board::{Ball, Gravity, Peg};

    fn make_peg(x: f32, y: f32) -> Peg {
        Peg::new(x, y)
    }

    /// Two balls heading toward each other should bounce.
    #[test]
    fn test_ball_ball_collision() {
        let mut a = Ball::new(100.0, 100.0, 100.0, 0.0);
        let mut b = Ball::new(120.0, 100.0, -100.0, 0.0);
        resolve_ball_ball(&mut a, &mut b);
        // After collision, velocities should change (they bounced).
        assert!(
            (a.vx - b.vx).abs() > 1.0,
            "velocities should diverge after collision"
        );
    }

    /// Ball heading into a peg should bounce and increment counter.
    #[test]
    fn test_ball_peg_collision() {
        let mut ball = Ball::new(100.0, 100.0, 50.0, 0.0);
        let peg = make_peg(120.0, 100.0);
        let hit = resolve_ball_peg(&mut ball, &peg);
        assert!(hit, "ball should hit peg");
        assert!(ball.vx < 0.0, "ball should bounce back");
    }

    /// Spawn-overlap: a ball spawned inside a peg should be rejected.
    #[test]
    fn test_spawn_overlap_rejection() {
        let mut board = crate::board::Board::new(42);
        board.add_peg(400.0, 300.0).unwrap();
        let len_before = board.balls.len();
        // Spawn ball right on top of the peg.
        board.add_ball(400.0, 300.0, 0.0, 0.0);
        assert_eq!(
            board.balls.len(),
            len_before,
            "ball should not be added when overlapping a peg"
        );
    }

    /// Determinism: same seed + same pegs → identical final state.
    #[test]
    fn test_determinism() {
        let mut board = crate::board::Board::new(12345);
        board.add_peg(300.0, 200.0).unwrap();
        board.add_peg(400.0, 250.0).unwrap();
        board.add_peg(500.0, 300.0).unwrap();

        let a = simulate_headless(&board.pegs, 12345, 600, Gravity::Down);
        let b = simulate_headless(&board.pegs, 12345, 600, Gravity::Down);

        assert_eq!(a.total_hits, b.total_hits, "total hits must match");
        assert_eq!(a.hot_peg_id, b.hot_peg_id, "hot peg must match");
        assert_eq!(a.hot_peg_hits, b.hot_peg_hits, "hot peg hits must match");
        assert_eq!(a.ball_positions.len(), b.ball_positions.len());
        for (pa, pb) in a.ball_positions.iter().zip(b.ball_positions.iter()) {
            assert!(
                (pa.0 - pb.0).abs() < 0.001,
                "ball x positions must match"
            );
            assert!(
                (pa.1 - pb.1).abs() < 0.001,
                "ball y positions must match"
            );
        }
    }
}

