use rusqlite::{Connection, Result as SqlResult};
use serde_json;
use std::path::Path;

use crate::board::{Gravity, Peg};

const DB_PATH: &str = "pegfall.db";

/// Open (or create) the database and ensure tables exist.
pub fn open_db() -> SqlResult<Connection> {
    let exists = Path::new(DB_PATH).exists();
    let conn = Connection::open(DB_PATH)?;
    if !exists {
        conn.execute_batch(
            "
            CREATE TABLE layouts (
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                name        TEXT NOT NULL DEFAULT 'untitled',
                seed        INTEGER NOT NULL,
                created_at  TEXT NOT NULL DEFAULT (datetime('now')),
                pegs_json   TEXT NOT NULL
            );
            CREATE TABLE runs (
                id              INTEGER PRIMARY KEY AUTOINCREMENT,
                layout_id       INTEGER NOT NULL,
                seed            INTEGER NOT NULL,
                ticks           INTEGER NOT NULL,
                total_hits      INTEGER NOT NULL,
                histogram_json  TEXT NOT NULL,
                created_at      TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (layout_id) REFERENCES layouts(id)
            );
            CREATE TABLE settings (
                key   TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );
            INSERT OR IGNORE INTO settings VALUES ('gravity', 'Down');
            INSERT OR IGNORE INTO settings VALUES ('labels_visible', 'false');
            ",
        )?;
    }
    Ok(conn)
}

/// Save the current layout (pegs + seed) as a new row.
pub fn save_layout(conn: &Connection, name: &str, seed: u64, pegs: &[Peg]) -> SqlResult<i64> {
    let pegs_json = serde_json::to_string(pegs).unwrap_or_else(|_| "[]".to_string());
    conn.execute(
        "INSERT INTO layouts (name, seed, pegs_json) VALUES (?1, ?2, ?3)",
        rusqlite::params![name, seed, pegs_json],
    )?;
    Ok(conn.last_insert_rowid())
}

/// Load the most recent layout.
pub fn load_latest_layout(conn: &Connection) -> SqlResult<Option<(i64, u64, Vec<Peg>)>> {
    let mut stmt = conn.prepare(
        "SELECT id, seed, pegs_json FROM layouts ORDER BY created_at DESC LIMIT 1",
    )?;
    let mut rows = stmt.query_map([], |row| {
        let id: i64 = row.get(0)?;
        let seed: u64 = row.get(1)?;
        let json: String = row.get(2)?;
        let pegs: Vec<Peg> = serde_json::from_str(&json).unwrap_or_default();
        Ok((id, seed, pegs))
    })?;
    match rows.next() {
        Some(Ok(result)) => Ok(Some(result)),
        _ => Ok(None),
    }
}

/// Record a completed run.
pub fn save_run(
    conn: &Connection,
    layout_id: i64,
    seed: u64,
    ticks: u64,
    total_hits: u32,
    pegs: &[Peg],
) -> SqlResult<i64> {
    let histogram: Vec<u32> = pegs.iter().map(|p| p.hit_count).collect();
    let histogram_json = serde_json::to_string(&histogram).unwrap_or_else(|_| "[]".to_string());
    conn.execute(
        "INSERT INTO runs (layout_id, seed, ticks, total_hits, histogram_json) VALUES (?1, ?2, ?3, ?4, ?5)",
        rusqlite::params![layout_id, seed, ticks, total_hits, histogram_json],
    )?;
    Ok(conn.last_insert_rowid())
}

/// Read a setting value.
pub fn get_setting(conn: &Connection, key: &str) -> SqlResult<Option<String>> {
    let mut stmt = conn.prepare("SELECT value FROM settings WHERE key = ?1")?;
    let mut rows = stmt.query_map(rusqlite::params![key], |row| row.get::<_, String>(0))?;
    match rows.next() {
        Some(Ok(v)) => Ok(Some(v)),
        _ => Ok(None),
    }
}

/// Write a setting value.
pub fn set_setting(conn: &Connection, key: &str, value: &str) -> SqlResult<()> {
    conn.execute(
        "INSERT OR REPLACE INTO settings (key, value) VALUES (?1, ?2)",
        rusqlite::params![key, value],
    )?;
    Ok(())
}

/// Load gravity setting, defaulting to Down.
pub fn load_gravity(conn: &Connection) -> Gravity {
    match get_setting(conn, "gravity") {
        Ok(Some(v)) => match v.as_str() {
            "Up" => Gravity::Up,
            "ZeroG" => Gravity::ZeroG,
            _ => Gravity::Down,
        },
        _ => Gravity::Down,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_db_round_trip() {
        // Use in-memory DB for testing.
        let conn = Connection::open_in_memory().unwrap();
        conn.execute_batch(
            "
            CREATE TABLE layouts (
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                name        TEXT NOT NULL DEFAULT 'untitled',
                seed        INTEGER NOT NULL,
                created_at  TEXT NOT NULL DEFAULT (datetime('now')),
                pegs_json   TEXT NOT NULL
            );
            CREATE TABLE runs (
                id              INTEGER PRIMARY KEY AUTOINCREMENT,
                layout_id       INTEGER NOT NULL,
                seed            INTEGER NOT NULL,
                ticks           INTEGER NOT NULL,
                total_hits      INTEGER NOT NULL,
                histogram_json  TEXT NOT NULL,
                created_at      TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (layout_id) REFERENCES layouts(id)
            );
            CREATE TABLE settings (
                key   TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );
            ",
        )
        .unwrap();

        let pegs = vec![Peg::new(100.0, 200.0), Peg::new(300.0, 400.0)];
        let layout_id = save_layout(&conn, "test", 42, &pegs).unwrap();
        assert!(layout_id > 0);

        let run_id = save_run(&conn, layout_id, 42, 600, 5, &pegs).unwrap();
        assert!(run_id > 0);

        let loaded = load_latest_layout(&conn).unwrap().unwrap();
        assert_eq!(loaded.1, 42);
        assert_eq!(loaded.2.len(), 2);
        assert_eq!(loaded.2[0].x, 100.0);
    }
}

