use crate::board::{Board, Gravity};
use crate::determinism::SeededRng;
use crate::physics;

/// Result of processing one frame of input.
#[derive(Debug)]
pub enum Action {
    None,
    AddPeg(f32, f32),
    RemovePeg(f32, f32),
    DropBall,
    SpawnDragBall(f32, f32, f32, f32),
    CycleGravity,
    PauseToggle,
    ClearBalls,
    ResetCounters,
    Reseed(u64),
    ToggleLabels,
    SaveLayout,
    LoadLayout,
    RecordRun,
    Quit,
}

/// Process all input events for the current frame.
/// `mouse_down` is true while the primary button is held.
/// `mouse_pressed` is true only on the frame the button went down.
pub fn process_input(
    board: &Board,
    rng: &mut SeededRng,
) -> Action {
    use macroquad::prelude::*;

    // Quit
    if is_key_pressed(KeyCode::Escape) {
        return Action::Quit;
    }

    // Gravity cycle: G
    if is_key_pressed(KeyCode::G) {
        return Action::CycleGravity;
    }

    // Pause: Space
    if is_key_pressed(KeyCode::Space) {
        return Action::PauseToggle;
    }

    // Clear balls: C
    if is_key_pressed(KeyCode::C) {
        return Action::ClearBalls;
    }

    // Reset counters: 0
    if is_key_pressed(KeyCode::Key0) {
        return Action::ResetCounters;
    }

    // Reseed: N
    if is_key_pressed(KeyCode::N) {
        let new_seed = rand_u64();
        return Action::Reseed(new_seed);
    }

    // Toggle labels: Tab
    if is_key_pressed(KeyCode::Tab) {
        return Action::ToggleLabels;
    }

    // Save layout: F5
    if is_key_pressed(KeyCode::F5) {
        return Action::SaveLayout;
    }

    // Load layout: F9
    if is_key_pressed(KeyCode::F9) {
        return Action::LoadLayout;
    }

    // Record run: R
    if is_key_pressed(KeyCode::R) {
        return Action::RecordRun;
    }

    // Drop ball: B
    if is_key_pressed(KeyCode::B) {
        return Action::DropBall;
    }

    // Mouse interactions
    let (mx, my) = (mouse_position().0, mouse_position().1);

    // Right-click: remove peg
    if is_mouse_button_pressed(MouseButton::Right) {
        return Action::RemovePeg(mx, my);
    }

    // Left-click drag: spawn ball with drag velocity
    if is_mouse_button_down(MouseButton::Left) {
        // On the frame it was pressed, record start.
        // Actually, we handle "drag" in main loop by tracking mouse state
    }

    // Left-click: place peg or spawn ball on click
    if is_mouse_button_pressed(MouseButton::Left) {
        return Action::AddPeg(mx, my);
    }

    Action::None
}

/// Simple random u64 using system time for reseed action.
fn rand_u64() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    dur.as_nanos() as u64
}

