use crate::board::{Ball, Board, Gravity, Peg, MAX_BALLS, MAX_PEGS};

/// Heat-map color: interpolate from blue (0 hits) → green → yellow → red (high hits).
fn heat_color(hit_count: u32, max_hits: u32) -> macroquad::color::Color {
    if max_hits == 0 {
        return macroquad::color::BLUE;
    }
    let t = (hit_count as f32 / max_hits as f32).min(1.0);
    // Blue → Cyan → Green → Yellow → Red
    use macroquad::color::Color;
    if t < 0.25 {
        let lt = t / 0.25;
        Color::new(0.0, lt, 1.0, 1.0) // blue → cyan
    } else if t < 0.5 {
        let lt = (t - 0.25) / 0.25;
        Color::new(0.0, 1.0, 1.0 - lt, 1.0) // cyan → green
    } else if t < 0.75 {
        let lt = (t - 0.5) / 0.25;
        Color::new(lt, 1.0, 0.0, 1.0) // green → yellow
    } else {
        let lt = (t - 0.75) / 0.25;
        Color::new(1.0, 1.0 - lt, 0.0, 1.0) // yellow → red
    }
}

/// Draw the complete board + HUD.
pub fn draw_board(
    board: &Board,
    paused: bool,
    labels_visible: bool,
    is_paused_frame: bool,
) {
    use macroquad::prelude::*;

    clear_background(BLACK);

    // Draw board border.
    draw_rectangle_lines(0.0, 0.0, 800.0, 600.0, 2.0, DARKGRAY);

    // Determine max hits for heat scale.
    let max_hits = board.pegs.iter().map(|p| p.hit_count).max().unwrap_or(0);

    // Draw pegs.
    for (i, peg) in board.pegs.iter().enumerate() {
        let color = if max_hits > 0 && peg.hit_count > 0 {
            heat_color(peg.hit_count, max_hits)
        } else {
            Color::new(0.3, 0.5, 0.8, 1.0) // default blue-gray
        };
        draw_circle(peg.x, peg.y, peg.radius, color);
        draw_circle_lines(peg.x, peg.y, peg.radius, 1.0, WHITE);

        // Numeric label on Tab.
        if labels_visible {
            let label = format!("{}", peg.hit_count);
            let text_size = 12.0;
            let text_w = measure_text(&label, None, text_size as u16, 1.0).width;
            draw_text(
                &label,
                peg.x - text_w / 2.0,
                peg.y + 4.0,
                text_size,
                WHITE,
            );
        }
    }

    // Draw balls.
    for ball in &board.balls {
        draw_circle(ball.x, ball.y, ball.radius, WHITE);
        draw_circle_lines(ball.x, ball.y, ball.radius, 1.0, LIGHTGRAY);
    }

    // Draw HUD.
    draw_hud(board, paused, labels_visible);
}

fn draw_hud(board: &Board, paused: bool, labels_visible: bool) {
    use macroquad::prelude::*;

    // Top-left info block.
    let mut y = 16.0;
    let line_h = 16.0;
    let text_size = 14.0;

    draw_text(&format!("Seed: {}", board.seed), 8.0, y, text_size, GREEN);
    y += line_h;
    draw_text(
        &format!("Gravity: {}", board.gravity.label()),
        8.0,
        y,
        text_size,
        YELLOW,
    );
    y += line_h;
    draw_text(
        &format!("Balls: {}/{}", board.balls.len(), MAX_BALLS),
        8.0,
        y,
        text_size,
        WHITE,
    );
    y += line_h;
    draw_text(
        &format!("Pegs: {}/{}", board.peg_count(), MAX_PEGS),
        8.0,
        y,
        text_size,
        WHITE,
    );
    y += line_h;
    draw_text(
        &format!("Total hits: {}", board.total_hits),
        8.0,
        y,
        text_size,
        WHITE,
    );
    y += line_h;

    // Hot peg.
    if let Some((idx, count, pct)) = board.hot_peg() {
        draw_text(
            &format!("Hot peg #{}: {} hits ({:.1}%)", idx, count, pct),
            8.0,
            y,
            text_size,
            RED,
        );
    } else if board.total_hits == 0 {
        draw_text("No hits yet", 8.0, y, text_size, DARKGRAY);
    } else {
        draw_text("No pegs placed", 8.0, y, text_size, DARKGRAY);
    }
    y += line_h + 4.0;

    // Pause indicator.
    if paused {
        draw_text("** PAUSED **", 8.0, y, text_size, ORANGE);
        y += line_h;
    }

    // Controls reference (bottom of HUD).
    y = 500.0;
    let controls = [
        "L-Click: place peg | R-Click: remove peg",
        "B: drop ball | Drag: spawn ball with velocity",
        "G: cycle gravity | Space: pause",
        "C: clear balls | 0: reset counters | N: reseed",
        "Tab: toggle labels | F5: save | F9: load | R: record run",
        "Esc: quit",
    ];
    for line in &controls {
        draw_text(line, 8.0, y, 12.0, GRAY);
        y += 14.0;
    }
}

