mod board;
mod controls;
mod db;
mod determinism;
mod physics;
mod render;

use board::{Ball, Board, Gravity, MAX_BALLS};
use controls::Action;
use determinism::SeededRng;
use physics::PhysicsSummary;

use std::env;

// Global state accessible from the macroquad context.
struct GameState {
    board: Board,
    rng: SeededRng,
    paused: bool,
    labels_visible: bool,
    layout_name: String,
    toast: Option<(String, f64)>, // (message, expiry_tick)
    current_layout_id: Option<i64>,
    // Track mouse drag for ball spawning.
    drag_start: Option<(f32, f32)>,
}

impl GameState {
    fn new(seed: u64) -> Self {
        Self {
            board: Board::new(seed),
            rng: SeededRng::new(seed),
            paused: false,
            labels_visible: false,
            layout_name: "untitled".to_string(),
            toast: None,
            current_layout_id: None,
            drag_start: None,
        }
    }

    fn show_toast(&mut self, msg: &str) {
        self.toast = Some((msg.to_string(), self.board.tick_count as f64 + 180.0));
    }
}

/// Run the interactive (windowed) mode.
#[macroquad::main("Pegfall Lab")]
async fn main() {
    let mut args = env::args().skip(1);
    let headless = args.any(|a| a == "--headless");

    if headless {
        let seed = parse_arg("--seed", 7);
        let ticks = parse_arg("--ticks", 600);
        run_headless(seed, ticks);
        return;
    }

    // Seed from CLI or random.
    let seed = parse_arg("--seed", {
        use std::time::{SystemTime, UNIX_EPOCH};
        let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
        (dur.as_nanos() % 1_000_000) as u64
    });

    let mut state = GameState::new(seed);

    // Load saved settings.
    let conn = db::open_db().unwrap_or_else(|e| {
        eprintln!("Warning: could not open DB ({}) — running without persistence", e);
        // Use a dummy in-memory replacement by returning early-ish — actually keep going.
        // We'll recreate on each save/load op.
        let _ = e;
        db::open_db().expect("fallback DB open")
    });

    state.board.gravity = db::load_gravity(&conn);
    state.labels_visible = db::get_setting(&conn, "labels_visible")
        .ok()
        .flatten()
        .map(|v| v == "true")
        .unwrap_or(false);

    // Try to load the latest saved layout.
    if let Ok(Some((id, seed, pegs))) = db::load_latest_layout(&conn) {
        state.board = Board::new(seed);
        state.board.pegs = pegs;
        state.board.gravity = db::load_gravity(&conn);
        state.current_layout_id = Some(id);
        state.show_toast("Loaded last layout");
    }

    drop(conn);

    let mut frame_count = 0u64;
    let mut physics_accumulator = 0.0f64;

    loop {
        // --- Input ---
        let action = controls::process_input(&state.board, &mut state.rng);

        match action {
            Action::Quit => break,
            Action::AddPeg(x, y) => {
                match state.board.add_peg(x, y) {
                    Ok(()) => {}
                    Err(msg) => state.show_toast(msg),
                }
            }
            Action::RemovePeg(x, y) => {
                state.board.remove_peg_at(x, y);
            }
            Action::DropBall => {
                let bx = 400.0 + state.rng.jitter(20.0);
                state.board.add_ball(bx, 30.0, 0.0, 50.0);
            }
            Action::SpawnDragBall(x, y, vx, vy) => {
                state.board.add_ball(x, y, vx, vy);
            }
            Action::CycleGravity => {
                state.board.gravity = state.board.gravity.cycle();
                // Persist gravity.
                if let Ok(conn) = db::open_db() {
                    let _ = db::set_setting(
                        &conn,
                        "gravity",
                        match state.board.gravity {
                            Gravity::Down => "Down",
                            Gravity::Up => "Up",
                            Gravity::ZeroG => "ZeroG",
                        },
                    );
                }
            }
            Action::PauseToggle => {
                state.paused = !state.paused;
            }
            Action::ClearBalls => {
                state.board.clear_balls();
            }
            Action::ResetCounters => {
                state.board.reset_counters();
            }
            Action::Reseed(new_seed) => {
                state.board.seed = new_seed;
                state.rng = SeededRng::new(new_seed);
                state.show_toast(&format!("Reseeded to {}", new_seed));
            }
            Action::ToggleLabels => {
                state.labels_visible = !state.labels_visible;
                if let Ok(conn) = db::open_db() {
                    let _ = db::set_setting(
                        &conn,
                        "labels_visible",
                        if state.labels_visible { "true" } else { "false" },
                    );
                }
            }
            Action::SaveLayout => {
                if let Ok(conn) = db::open_db() {
                    match db::save_layout(
                        &conn,
                        &state.layout_name,
                        state.board.seed,
                        &state.board.pegs,
                    ) {
                        Ok(id) => {
                            state.current_layout_id = Some(id);
                            state.show_toast(&format!(
                                "Layout saved ({} pegs, seed {})",
                                state.board.peg_count(),
                                state.board.seed
                            ));
                        }
                        Err(e) => state.show_toast(&format!("Save error: {}", e)),
                    }
                } else {
                    state.show_toast("DB unavailable");
                }
            }
            Action::LoadLayout => {
                if let Ok(conn) = db::open_db() {
                    match db::load_latest_layout(&conn) {
                        Ok(Some((id, seed, pegs))) => {
                            state.current_layout_id = Some(id);
                            state.board = Board::new(seed);
                            state.board.pegs = pegs;
                            state.board.gravity = db::load_gravity(&conn);
                            state.board.seed = seed;
                            state.rng = SeededRng::new(seed);
                            state.show_toast("Layout loaded");
                        }
                        Ok(None) => state.show_toast("No saved layout"),
                        Err(e) => state.show_toast(&format!("Load error: {}", e)),
                    }
                } else {
                    state.show_toast("DB unavailable");
                }
            }
            Action::RecordRun => {
                if state.board.total_hits > 0 {
                    if let Ok(conn) = db::open_db() {
                        let layout_id = state.current_layout_id.unwrap_or(0);
                        match db::save_run(
                            &conn,
                            layout_id,
                            state.board.seed,
                            state.board.tick_count,
                            state.board.total_hits,
                            &state.board.pegs,
                        ) {
                            Ok(id) => {
                                state.show_toast(&format!(
                                    "Run recorded (#{}): {} hits",
                                    id,
                                    state.board.total_hits
                                ));
                            }
                            Err(e) => state.show_toast(&format!("Record error: {}", e)),
                        }
                    } else {
                        state.show_toast("DB unavailable");
                    }
                } else {
                    state.show_toast("No hits to record");
                }
            }
            Action::None => {}
        }

        // --- Physics update (fixed timestep) ---
        if !state.paused {
            let (gx, gy) = state.board.gravity.acceleration();
            // Fixed timestep: 8 substeps per frame assuming 60 fps → 120 Hz.
            const SUBSTEPS: u64 = 8;
            frame_count += 1;
            state.board.tick_count += SUBSTEPS;
            let hits = physics::step(
                &mut state.board.balls,
                &mut state.board.pegs,
                gx,
                gy,
                SUBSTEPS,
            );
            state.board.total_hits += hits;
        }

        // --- Mouse drag handling ---
        use macroquad::prelude::*;
        if is_mouse_button_pressed(MouseButton::Left) {
            let (mx, my) = mouse_position();
            state.drag_start = Some((mx, my));
        }
        if is_mouse_button_released(MouseButton::Left) {
            if let Some((sx, sy)) = state.drag_start {
                let (mx, my) = mouse_position();
                let dx = mx - sx;
                let dy = my - sy;
                // If drag distance > 15 pixels, treat as drag-spawn.
                if dx * dx + dy * dy > 15.0 * 15.0 {
                    // Use start position for spawn, drag vector for velocity.
                    state.board.add_ball(sx, sy, dx * 3.0, dy * 3.0);
                }
            }
            state.drag_start = None;
        }

        // --- Render ---
        render::draw_board(&state.board, state.paused, state.labels_visible, false);

        // Draw toast.
        if let Some((ref msg, expiry)) = state.toast {
            if (state.board.tick_count as f64) < expiry {
                let text = format!("[ {} ]", msg);
                let text_size = 16.0;
                let text_w =
                    macroquad::text::measure_text(&text, None, text_size as u16, 1.0).width;
                macroquad::text::draw_text(
                    &text,
                    400.0 - text_w / 2.0,
                    300.0,
                    text_size,
                    macroquad::color::YELLOW,
                );
            } else {
                state.toast = None;
            }
        }

        // --- Drag visualization ---
        if let Some((sx, sy)) = state.drag_start {
            if is_mouse_button_down(MouseButton::Left) {
                let (mx, my) = mouse_position();
                let dx = mx - sx;
                let dy = my - sy;
                if dx * dx + dy * dy > 15.0 * 15.0 {
                    draw_line(sx, sy, mx, my, 1.0, macroquad::color::GRAY);
                    draw_circle(sx, sy, 5.0, macroquad::color::Color::new(1.0, 1.0, 1.0, 0.3));
                }
            }
        }

        next_frame().await;
    }

    // Autosave layout on quit.
    if let Ok(conn) = db::open_db() {
        if state.board.peg_count() > 0 {
            let _ = db::save_layout(
                &conn,
                &state.layout_name,
                state.board.seed,
                &state.board.pegs,
            );
        }
        let _ = db::set_setting(
            &conn,
            "gravity",
            match state.board.gravity {
                Gravity::Down => "Down",
                Gravity::Up => "Up",
                Gravity::ZeroG => "ZeroG",
            },
        );
    }
}

/// Run headless simulation and print summary.
fn run_headless(seed: u64, ticks: u64) {
    // Build a deterministic peg layout.
    let mut rng = SeededRng::new(seed);
    let mut pegs = Vec::new();

    // Place a standard array of pegs (same for any seed — positions derived from seed).
    let peg_positions = generate_layout(&mut rng);
    for (x, y) in peg_positions {
        pegs.push(board::Peg::new(x, y));
    }

    let summary = physics::simulate_headless(&pegs, seed, ticks, Gravity::Down);

    println!("=== Pegfall Lab — Headless Report ===");
    println!("Seed:     {}", seed);
    println!("Ticks:    {}", ticks);
    println!("Pegs:     {}", pegs.len());
    println!("Hits:     {}", summary.total_hits);
    println!("Hot peg:  #{} ({} hits)",
        summary.hot_peg_id.map(|i| i.to_string()).unwrap_or_else(|| "none".to_string()),
        summary.hot_peg_hits);
    println!(
        "Balls:    {} (final positions: {:?})",
        summary.ball_positions.len(),
        summary.ball_positions
    );

    // Checksum: round all positions to 2dp and sum.
    let checksum: f64 = summary
        .ball_positions
        .iter()
        .flat_map(|(x, y)| vec![*x as f64, *y as f64])
        .map(|v| (v * 100.0).round() / 100.0)
        .sum();
    println!("Checksum: {:.2}", checksum);

    // Run a second time and compare for determinism guarantee.
    let summary2 = physics::simulate_headless(&pegs, seed, ticks, Gravity::Down);
    let checksum2: f64 = summary2
        .ball_positions
        .iter()
        .flat_map(|(x, y)| vec![*x as f64, *y as f64])
        .map(|v| (v * 100.0).round() / 100.0)
        .sum();
    let deterministic = (checksum - checksum2).abs() < 0.01
        && summary.total_hits == summary2.total_hits;
    println!("Deterministic: {}", if deterministic { "YES ✓" } else { "NO ✗" });
}

/// Generate a deterministic peg layout from a seeded RNG.
/// Produces a 5×8 grid with some jitter.
fn generate_layout(rng: &mut SeededRng) -> Vec<(f32, f32)> {
    let mut positions = Vec::new();
    for row in 0..5 {
        let y = 100.0 + row as f32 * 100.0;
        let cols = if row % 2 == 0 { 8 } else { 7 };
        let offset_x = if row % 2 == 0 { 70.0 } else { 120.0 };
        for col in 0..cols {
            let x = offset_x + col as f32 * 90.0 + rng.jitter(15.0) as f32;
            let yj = y + rng.jitter(10.0) as f32;
            positions.push((x, yj));
        }
    }
    positions
}

fn parse_arg(name: &str, default: u64) -> u64 {
    let args: Vec<String> = env::args().collect();
    for i in 1..args.len() - 1 {
        if args[i] == name {
